//go:build darwin || linux

package projectsqlmigrateproduct_test

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const (
	sqlProductPostgresSchema       = "sql_product_schema"
	sqlProductPostgresPoisonSchema = "mutated_after_snapshot_schema"

	sqlProductPostgresAuthorOutput = "CREATE TABLE \"sql_product_schema\".\"authors_author\" (" +
		"\"id\" BIGINT GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME \"sql_product_schema\".\"godj_seq_2b6d95c7e774075bdbd96461ee7d19c4a777065e86dbbb76\" " +
		"START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL, " +
		"\"name\" VARCHAR(100) NOT NULL, CONSTRAINT \"godj_pk_2bbcf95a5d3006979af1c02f365beccad445a3eb1001ec0e\" PRIMARY KEY (\"id\"));\n"
	sqlProductPostgresEnrichOutput = "ALTER TABLE \"sql_product_schema\".\"blog_article\" ADD COLUMN \"summary\" VARCHAR(120) NULL;\n" +
		"ALTER TABLE \"sql_product_schema\".\"blog_article\" ADD COLUMN \"published\" BOOLEAN NOT NULL;\n"
)

func TestGlobalSQLMigrateExternalPhaseDProduct(t *testing.T) {
	for _, key := range []string{
		"DATABASE_URL",
		"GODJ_ARTICLE_DATABASE_URL",
		"GODJ_ARTICLE_POSTGRES_URL",
		"GODJ_E2E_POSTGRES_URL",
		"GODJ_SHOWMIGRATIONS_POSTGRES_URL",
		"GODJ_TARGET_MIGRATE_POSTGRES_URL",
		"GODJ_TEST_POSTGRES_URL",
		"PGHOST",
		"PGPASSWORD",
		"PGSERVICEFILE",
		"POSTGRES_DB",
		"POSTGRES_HOST",
		"POSTGRES_PASSWORD",
		"POSTGRES_PORT",
		"POSTGRES_USER",
		"POSTGRESQL_URL",
		"POSTGRES_URL",
	} {
		t.Setenv(key, sqlProductHostedDatabaseCanary+"-"+strings.ToLower(key))
	}
	project := newSQLProductProject(t)
	baselineAttempts := project.assertNoPostgresConnectionAttempts(t)

	t.Run("PostgreSQL schema-only renderer is exact frozen and database-free", func(t *testing.T) {
		project.assertPostgresRunnerDBFree(t)

		authorState := project.state(t, "postgres-create-author")
		authorEnvironment := project.postgresEnvironment(authorState)
		sqlProductAssertPostgresEnvironmentSanitized(t, authorEnvironment, project.postgresPoison)
		author := project.runExplicit(t, authorState, authorEnvironment, "authors", "0001_author")
		sqlProductAssertSuccess(t, author, sqlProductPostgresAuthorOutput, project.sensitive(authorState)...)
		authorAttempts := project.assertNoPostgresConnectionAttempts(t)
		sqlProductAssertMarker(t, authorState.initMarker, "init")
		sqlProductAssertMarker(t, authorState.rendererMarker, "render")

		enrichState := project.state(t, "postgres-add-fields")
		enrichEnvironment := project.postgresEnvironment(enrichState)
		sqlProductAssertPostgresEnvironmentSanitized(t, enrichEnvironment, project.postgresPoison)
		enrich := project.runExplicit(t, enrichState, enrichEnvironment, "blog", "0002_enrich")
		sqlProductAssertSuccess(t, enrich, sqlProductPostgresEnrichOutput, project.sensitive(enrichState)...)
		enrichAttempts := project.assertNoPostgresConnectionAttempts(t)
		sqlProductAssertMarker(t, enrichState.initMarker, "init")
		sqlProductAssertMarker(t, enrichState.rendererMarker, "render")
		observed := [3]int64{baselineAttempts, authorAttempts, enrichAttempts}
		if observed != ([3]int64{}) {
			t.Fatalf("PostgreSQL connection-attempt observations = %v, want [0 0 0]", observed)
		}
		t.Logf("PostgreSQL connection-attempt observations = %v", observed)

		combined := author.stdout + enrich.stdout
		if !strings.Contains(combined, `"`+sqlProductPostgresSchema+`".`) ||
			strings.Contains(combined, sqlProductPostgresPoisonSchema) {
			t.Fatalf("PostgreSQL SQL did not retain the frozen schema profile: %q", combined)
		}
	})

	t.Run("actual OS interruption cancels and reaps the built runner", func(t *testing.T) {
		state := project.state(t, "actual-child-interruption")
		environment := project.environment(state, sqlProductCatalogFull, sqlProductRendererWaitCancel)
		result := project.runInterrupted(t, state, environment, "authors", "0001_author")
		sqlProductAssertFailure(
			t,
			result,
			130,
			"migration_project_process_error/project_interrupted\n",
			project.sensitive(state)...,
		)
		if len(result.stdout) != 0 {
			t.Fatalf("interrupted sqlmigrate stdout bytes = %d, want 0", len(result.stdout))
		}
		sqlProductAssertMarker(t, state.initMarker, "init")
		sqlProductAssertMarker(t, state.rendererMarker, "render_wait")
	})

	t.Run("runner pipeline audit rejects hardcoded stubs", func(t *testing.T) {
		sqlProductAssertRunnerPipelineAuditRejectsHardcodedStubs(t, project)
	})

	sqlProductAuditApplicationSources(t, project.repository, project.root)
	project.assertApplicationUnchanged(t)
	project.assertWorkspaceEmpty(t)
}

func sqlProductAssertRunnerPipelineAuditRejectsHardcodedStubs(t *testing.T, project *sqlProductProject) {
	t.Helper()
	if err := sqlProductAuditRunnerPipeline([]byte(sqlProductRunnerSource)); err != nil {
		t.Fatalf("audit actual external project runner: %v", err)
	}
	tests := []struct {
		name         string
		old          string
		new          string
		suffix       string
		compileValid bool
	}{
		{
			name: "project Run bypass",
			old:  "err = project.Run(context.Background(), project.Config{",
			new:  "err = hardcodedRun(context.Background(), project.Config{",
		},
		{
			name: "definition sources bypass",
			old:  "MigrationDefinitionSources: sources,",
			new:  "MigrationDefinitionSources: nil,",
		},
		{
			name: "renderer bypass",
			old:  "MigrationSQLRenderer: rendererForMode(os.Getenv(rendererEnvironment)),",
			new:  "MigrationSQLRenderer: nil,",
		},
		{
			name: "source encoding bypass",
			old:  "document, err := definition.Encode(definition.Producer{Name: \"sqlmigrate-product\", Version: \"1\"}, migration)",
			new:  "document, err := hardcodedEncode(migration)",
		},
		{
			name: "hardcoded renderer output",
			old:  "return renderer.delegate.RenderForwardMigrationSQL(ctx, request)",
			new:  "return []string{\"CREATE TABLE hardcoded_stub\"}, nil",
		},
		{
			name:         "source selection result decoupled",
			old:          "sources, err := sourcesForCatalog(os.Getenv(catalogEnvironment))",
			new:          "sources := []definition.Source(nil)\n\t_, err := sourcesForCatalog(os.Getenv(catalogEnvironment))",
			compileValid: true,
		},
		{
			name:         "source selection result reassigned",
			old:          "sources, err := sourcesForCatalog(os.Getenv(catalogEnvironment))",
			new:          "sources, err := sourcesForCatalog(os.Getenv(catalogEnvironment))\n\tsources = []definition.Source(nil)",
			compileValid: true,
		},
		{
			name:         "encoded document result decoupled",
			old:          "document, err := definition.Encode(definition.Producer{Name: \"sqlmigrate-product\", Version: \"1\"}, migration)",
			new:          "encoded, err := definition.Encode(definition.Producer{Name: \"sqlmigrate-product\", Version: \"1\"}, migration)\n\t\tdocument := []byte(\"{}\")\n\t\t_ = encoded",
			compileValid: true,
		},
		{
			name:         "delegate result discarded for concatenated hardcoded SQL",
			old:          "return renderer.delegate.RenderForwardMigrationSQL(ctx, request)",
			new:          "_, _ = renderer.delegate.RenderForwardMigrationSQL(ctx, request)\n\treturn []string{\"CREATE \" + \"TABLE hardcoded_stub\"}, nil",
			compileValid: true,
		},
		{
			name:         "SQLite branch return decoupled",
			old:          "return observedRenderer{delegate: sqlite.NewMigrationSQLRenderer()}",
			new:          "_ = observedRenderer{delegate: sqlite.NewMigrationSQLRenderer()}\n\t\treturn failingRenderer{}",
			compileValid: true,
		},
		{
			name:         "PostgreSQL branch return decoupled",
			old:          "return observedRenderer{delegate: delegate}",
			new:          "_ = observedRenderer{delegate: delegate}\n\t\treturn failingRenderer{}",
			compileValid: true,
		},
		{
			name:         "unexpected hardcoded renderer type",
			old:          "return observedRenderer{delegate: sqlite.NewMigrationSQLRenderer()}",
			new:          "_ = observedRenderer{delegate: sqlite.NewMigrationSQLRenderer()}\n\t\treturn hardcodedRenderer{}",
			suffix:       "\n\ntype hardcodedRenderer struct{}\n\nfunc (hardcodedRenderer) RenderForwardMigrationSQL(context.Context, backend.ForwardMigrationSQLRequest) ([]string, error) {\n\treturn []string{\"CREATE \" + \"TABLE hardcoded_stub\"}, nil\n}\n",
			compileValid: true,
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if strings.Count(sqlProductRunnerSource, test.old) != 1 {
				t.Fatalf("mutation anchor count for %q is not one", test.old)
			}
			mutated := strings.Replace(sqlProductRunnerSource, test.old, test.new, 1) + test.suffix
			if test.compileValid {
				runner := filepath.Join(project.root, "cmd", "projectrunner", "main.go")
				sqlProductWriteFile(t, runner, []byte(mutated), 0o600)
				defer sqlProductWriteFile(t, runner, []byte(sqlProductRunnerSource), 0o600)
				sqlProductRunSuccess(t, project.root, project.baseEnv, "go", "test", "-run=^$", "./cmd/projectrunner")
			}
			if err := sqlProductAuditRunnerPipeline([]byte(mutated)); err == nil {
				t.Fatal("external project runner audit accepted a pipeline bypass")
			}
		})
	}
}

func (project *sqlProductProject) assertPostgresRunnerDBFree(t *testing.T) {
	t.Helper()
	document, err := os.ReadFile(filepath.Join(project.root, "cmd", "projectrunner", "main.go"))
	if err != nil {
		t.Fatal(err)
	}
	for _, forbidden := range [][]byte{
		[]byte(sqlProductPostgresURLEnvironment),
		[]byte("postgres.Open("),
		[]byte(`"database/sql"`),
	} {
		if bytes.Contains(document, forbidden) {
			t.Fatalf("external PostgreSQL SQL renderer source contains database-bearing token %q", forbidden)
		}
	}
}

func sqlProductAssertPostgresEnvironmentSanitized(
	t *testing.T,
	environment []string,
	poison *sqlProductPostgresPoison,
) {
	t.Helper()
	if poison == nil {
		t.Fatal("PostgreSQL poison listener is absent")
	}
	want := poison.environment()
	want[sqlProductPostgresURLEnvironment] = poison.url
	seen := make(map[string]struct{}, len(want))
	for _, entry := range environment {
		key, value, ok := strings.Cut(entry, "=")
		if !ok {
			continue
		}
		if strings.Contains(value, sqlProductHostedDatabaseCanary) {
			t.Fatalf("environment %s retained a simulated Hosted database value", key)
		}
		if !sqlProductIsDatabaseEnvironmentKey(key) && key != sqlProductPostgresURLEnvironment {
			continue
		}
		expected, exists := want[key]
		if !exists {
			t.Fatalf("environment retained unsanitized database key %s", key)
		}
		if value != expected {
			t.Fatalf("environment %s differs from its poison override", key)
		}
		seen[key] = struct{}{}
	}
	for key := range want {
		if _, ok := seen[key]; !ok {
			t.Fatalf("environment poison override %s is absent", key)
		}
	}
}
